{"code":"import random

def generate(rng):
    # 3x3 array of 5x5 cells separated by 7 lines; place several small 9 motifs
    H=W=17
    g=[[0]*W for _ in range(H)]
    for r in [5,11]:
        for c in range(W): g[r][c]=7
    for c in [5,11]:
        for r in range(H): g[r][c]=7
    motifs=[[(2,2)],[(1,2),(2,1),(2,2),(2,3),(3,2)],[(1,1),(1,2),(2,1),(2,2)],[(2,2),(3,2)]]
    for br in range(3):
      for bc in range(3):
        if rng.random()<.55:
          mot=rng.choice(motifs)
          for dr,dc in mot: g[br*6+dr][bc*6+dc]=9
    return g"}

